INSERT INTO `item_template` (`entry`, `class`, `subclass`, `name`, `displayid`, `Quality`, `Flags`, `BuyPrice`, `SellPrice`, `ItemLevel`, `RequiredSkill`, `RequiredSkillRank`, `delay`, `spellid_1`, `spellcharges_1`, `spellid_2`, `spelltrigger_2`, `bonding`, `description`, `Material`, `BagFamily`) VALUES
(400032, 15, 5, 'Tiger', 400032, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400032, 6, 1, '', -1, 0),
(400350, 15, 5, 'Sunwalker Kodo', 400350, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400350, 6, 1, 'This magnificent beast, adorned in sacred charms and painted with holy imagery, radiates with the warmth of the sun.', -1, 0),
(400351, 15, 5, 'Great Sunwalker Kodo', 400351, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400351, 6, 1, 'At daybreak, the noble Sunwalkers often perform rituals to bless their mounts, imbuing them with holy magic.', -1, 0),
(400367, 15, 5, 'Exarch\'s Elekk', 400367, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400367, 6, 1, 'Draenei exarchs have long marched into war atop these imposing mounts, bred for their razor-sharp tusks.', -1, 0),
(400368, 15, 5, 'Great Exarch\'s Elekk', 400368, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400368, 6, 1, 'Only the most distinguished paladins are given the honor of riding this elekk. Its plated armor and purple adornments have been blessed by Prophet Velen himself.', -1, 0),
(400373, 15, 5, 'Vashj\'ir Seahorse', 400373, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400373, 6, 1, 'Stubborn until broken, these underwater mounts provide the swiftest means of travel around the depths of Vashj\'ir.', -1, 0),
(400386, 15, 5, 'Fossilized Raptor', 400386, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400386, 6, 1, 'Legends tell of a spell placed upon a hunting raptor who dared to snarl at young Tyrande Whisperwind as she bathed in a jungle pool. The beast is cursed to wander Azeroth - until it apologizes.', -1, 0),
(400388, 15, 5, 'Goblin Trike', 400388, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400388, 6, 1, 'A compilation of nuts, bolts, gears, and treated wood paneling make for an unusually smooth ride.', -1, 0),
(400389, 15, 5, 'Goblin Turbo-Trike', 400389, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400389, 6, 1, 'The turbo trike\'s tri-wheel design adds superior stability and a smaller turn radius over its two wheeled cousins.', -1, 0),
(400391, 15, 5, 'Volcanic Stone Drake', 400391, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400391, 6, 1, 'Fire can transform stone in exciting ways, but never let the Stonemother know I said that. -Earthcaller Yevaa', -1, 0),
(400392, 15, 5, 'Drake of the East Wind', 400392, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400392, 6, 1, 'In Deathwing\'s mad quest to forge new dragons, he ignored amazing breeds never before seen on Azeroth. -Thrall', -1, 0),
(400393, 15, 5, 'Phosphorescent Stone Drake', 400393, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400393, 6, 1, 'The Stonemother has shown little concern for the rebellious Aeonaxx, even allowing his spawn to be taken from her realm.', -1, 0),
(400394, 15, 5, 'Drake of the West Wind', 400394, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400394, 6, 1, 'Harnessing the elemental powers of the storm, these majestic beasts crackle like lightning and roar like thunder.', -1, 0),
(400395, 15, 5, 'Drake of the North Wind', 400395, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400395, 6, 1, 'They sicken of the calm who know the storm.', -1, 0),
(400396, 15, 5, 'Drake of the South Wind', 400396, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400396, 6, 1, 'Gentle as a summer breeze, but that says little considering where it came from. -Itesh', -1, 0),
(400397, 15, 5, 'Vitreous Stone Drake', 400397, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400397, 6, 1, 'Those would be perfect in a pendant, and that would make a fantastic ring. Let me know if this thing sheds or molts or whatever. -Kalinda', -1, 0),
(400398, 15, 5, 'Brown Riding Camel', 400398, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400398, 6, 1, 'Fennimore Quigley is credited with milking the first camel and breaking the record for "longest unintentional flight," all in the same afternoon.', -1, 0),
(400399, 15, 5, 'Tan Riding Camel', 400399, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400399, 6, 1, 'Fennimore Quigley is credited with milking the first camel and breaking the record for "longest unintentional flight," all in the same afternoon.', -1, 0),
(400400, 15, 5, 'Grey Riding Camel', 400400, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400400, 6, 1, 'Fennimore Quigley is credited with milking the first camel and breaking the record for "longest unintentional flight," all in the same afternoon.', -1, 0),
(400404, 15, 5, 'Ultramarine Qiraji Battle Tank', 400404, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400404, 6, 1, 'The Tol\'vir sorcerer Azj\'Aqir was said to possess a scepter that would allow him to control a Qiraj battle tank outside of its Silithus home.', -1, 0),
(400405, 15, 5, 'Spectral Steed', 400405, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400405, 6, 1, 'Dark spirits flee before the radiance of its presence.', -1, 0),
(400406, 15, 5, 'Spectral Wolf', 400406, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400406, 6, 1, 'Fears only fire.', -1, 0),
(400408, 15, 5, 'Mottled Drake', 400408, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400408, 6, 1, 'I thought the thing was ill until it took to the air. It flies as true as any of my own. -Alexstrasza', -1, 0),
(400410, 15, 5, 'Armored Razzashi Raptor', 400410, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400410, 6, 1, 'The purebred royal raptors of Zul\'Gurub, these mounts have become a rare sight in Stranglethorn Vale. The Gurubashi have been known to fly into a rage at the sight of any non-troll riding one of their precious beasts.', -1, 0),
(400411, 15, 5, 'Swift Zulian Panther', 400411, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400411, 6, 1, 'The jungle trolls have long coveted panther fangs, using them for rituals or as ingredients in mojos.', -1, 0),
(400412, 15, 5, 'Amani Dragonhawk', 400412, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400412, 6, 1, 'Dragonhawks liberated from troll enslavement are considered among the most loyal of all their kin.', -1, 0),
(400413, 15, 5, 'Flameward Hippogryph', 400413, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400413, 6, 1, 'Flameward Hippogryphs revel in the defeat of Ragnaros, Lord of Fire.', -1, 0),
(400415, 15, 5, 'Pureblood Fire Hawk', 400415, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400415, 6, 1, 'Legends state that the Pureblood line may be traced back to the very creation of the Firelands.', -1, 0),
(400416, 15, 5, 'Felfire Hawk', 400416, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400416, 6, 1, 'Felfire is deadly to the touch. Luckily, the hawk can suppress the flames, choosing not to incinerate its rider in an emerald effigy.', -1, 0),
(400417, 15, 5, 'Corrupted Fire Hawk', 400417, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400417, 6, 1, 'Millagazor was a fire hawk loyal to Ragnaros. At this time it is unknown how many of Millagazor\'s eggs were corrupted.', -1, 0),
(400418, 15, 5, 'Savage Raptor', 400418, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400418, 6, 1, 'One-time companion of Kanga the Primal, the fallen troll hero. The raptor\'s name is unknown, for Kanga only spoke to it in bear form.', -1, 0),
(400419, 15, 5, 'Amani Battle Bear', 400419, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400419, 6, 1, 'The Amani trolls decorate these ferocious mounts in magic amulets and ceremonial masks as a way to venerate the bear god Nalorakk.', -1, 0),
(400420, 15, 5, 'Subdued Seahorse', 400420, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400420, 6, 1, 'One has not truly lived until they have felt the tidal current rushing through their hair while atop a majestic seahorse, said no one. Ever.', -1, 0),
(400421, 15, 5, 'Winged Guardian', 400421, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400421, 6, 1, 'Unearthed recently in an ancient tomb, this mighty winged lion may have once served one of the ancient Tol\'vir princes.', -1, 0),
(400422, 15, 5, 'Vicious War Steed', 400422, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400422, 6, 1, 'Armored to withstand collisions in battle.', -1, 0),
(400423, 15, 5, 'Vicious War Wolf', 400423, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400423, 6, 1, 'At Warchief Hellscream\'s command, Horde trainers began raising wolves to thrive in the shock and ferocity of sustained combat.', -1, 0),
(400424, 15, 5, 'Vicious Gladiator\'s Twilight Drake', 400424, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400424, 6, 1, 'Heroes who proved their might in the gladiatorial arenas during the Cataclysm were awarded the most exceptional of the twilight drake broods.', -1, 0),
(400425, 15, 5, 'Flametalon of Alysrazor', 400425, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400425, 6, 1, 'As with their matriarch, Alysrazor, the fury and fervor of these elemental avians are unquenchable.', -1, 0),
(400426, 15, 5, 'Swift Shorestrider', 400426, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400426, 6, 1, 'A rarity amongst the tallstrider breeds of Kalimdor, but easily recognized by its pungent dead seaweed aroma.', -1, 0),
(400428, 15, 5, 'Ruthless Gladiator\'s Twilight Drake', 400428, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400428, 6, 1, 'Heroes who proved their might in the gladiatorial arenas during the Cataclysm were awarded the most exceptional of the twilight drake broods.', -1, 0),
(400429, 15, 5, 'Swift Forest Strider', 400429, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400429, 6, 1, 'This vibrant breed can only be found in the forests of Darkmoon Island.', -1, 0),
(400430, 15, 5, 'Swift Springstrider', 400430, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400430, 6, 1, 'The joys of Noblegarden are best when celebrated with this loyal, loving, and blandly-colored freak of nature.', -1, 0),
(400431, 15, 5, 'Swift Lovebird', 400431, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400431, 6, 1, 'It\'s like red but not quite.', -1, 0),
(400432, 15, 5, 'White Riding Camel', 400432, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400432, 6, 1, 'Fennimore Quigley is credited with milking the first camel and breaking the record for "longest unintentional flight," all in the same afternoon.', -1, 0),
(400433, 15, 5, 'Corrupted Hippogryph', 400433, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400433, 6, 1, 'It is a sad fact that even the wise and majestic hippogryph may fall prey to corruption.', -1, 0),
(400434, 15, 5, 'Darkmoon Dancing Bear', 400434, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400434, 6, 1, 'These fearsome mounts have a habit of suddenly breaking out into dance amid battle, much to the annoyance of their riders.', -1, 0),
(400435, 15, 5, 'Mountain Horse', 400435, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400435, 6, 1, 'Images of this breed are often found on kegs of watered-down dwarven brew.', -1, 0),
(400436, 15, 5, 'Swift Mountain Horse', 400436, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400436, 6, 1, 'Longs for the day it may return to its home in Gilneas.', -1, 0),
(400439, 15, 5, 'Tyrael\'s Charger', 400439, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400439, 6, 1, 'A symbol of justice throughout all known realms.', -1, 0),
(400440, 15, 5, 'Spectral Gryphon', 400440, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400440, 6, 1, 'When you said an old friend was coming back, this was not quite what I expected. -Bralla Cloudwing', -1, 0),
(400441, 15, 5, 'Spectral Wind Rider', 400441, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400441, 6, 1, 'How do you not fall right through that thing? -Maztha', -1, 0),
(400442, 15, 5, 'Blazing Drake', 400442, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400442, 6, 1, 'Blazing Drakes exhibit a boundless passion for life, and are considered by many to be among the most loyal mounts on Azeroth.', -1, 0),
(400443, 15, 5, 'Twilight Harbinger', 400443, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400443, 6, 1, 'Whatever dark magic once compelled the Twilight Harbinger is now broken... or is it?', -1, 0),
(400444, 15, 5, 'Life-Binder\'s Handmaiden', 400444, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400444, 6, 1, 'Alexstrasza, the former dragon Aspect of Life, is known to be a kind and patient mentor. Under her tutelage, only the most dedicated pupils acquire the title of "Life-Binder\'s Handmaiden."', -1, 0),
(400445, 15, 5, 'Experiment 12-B', 400445, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400445, 6, 1, 'Some believe Experiment 12-B is the result of a covert SI-7 initiative, others consider it the outcome of embyronic tinkering by goblin scientists.', -1, 0),
(400446, 15, 5, 'Heart of the Aspects', 400446, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400446, 6, 1, 'You are Azeroth\'s true guardians and the future of this world is in your hands, for the dawning of the age of mortals has begun. - Alexstrasza', -1, 0),
(400447, 15, 5, 'Feldrake', 400447, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400447, 6, 1, 'Fighting the Burning Legion millennia ago, this valiant drake fell to corruption after its body was infused with raw demonic magic.', -1, 0),
(400448, 15, 5, 'Jade Cloud Serpent', 400448, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400448, 6, 1, 'Jade Cloud Serpents are light and agile; quick and deadly.', -1, 0),
(400449, 15, 5, 'Azure Water Strider', 400449, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400449, 6, 1, 'Normally bugs are for bait, but how could you look into its eyes and even think that? -Nat Pagle', -1, 0),
(400450, 15, 5, 'Pandaren Kite', 400450, 4, 0, 0, 0, 20, 762, 75, 0, 55884, -1, 400450, 6, 1, 'This "mount," awarded by the Lorewalkers of Pandaria, is a reward to the hero of their organization.', -1, 0),
