(411722, 15, 2, 'Dream Whelpling', 411722, 3, 64, 0, 0, 20, 0, 0, 0, 55884, -1, 411722, 6, 0, 'Beautiful dreamer, wake unto me, Starlight and dewdrops are waiting for thee.', -1, 4096),
(411723, 15, 2, 'Nightmare Whelpling', 411723, 3, 64, 0, 0, 20, 0, 0, 0, 55884, -1, 411723, 6, 0, 'What\'s a little corruption between friends?', -1, 4096),
(411725, 15, 2, 'Grumpling', 411725, 3, 64, 0, 0, 20, 0, 0, 0, 55884, -1, 411725, 6, 0, 'Grumplings are created when the tears of a kidnapped child fall upon a mound of new snow.', -1, 4096),
(411726, 15, 2, 'Burrow Spiderling', 411726, 3, 64, 0, 0, 20, 0, 0, 0, 55884, -1, 411726, 6, 0, 'The front legs of this spider are almost indestructable, allowing it to burrow into almost any surface.', -1, 4096),
